125	    @Override
126	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
127	        Owner owner = this.clinicService.findOwnerById(ownerId);
128	        if (owner == null) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return okOwnerResponse(owner);
