759	    /**
760	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
761	     * and a domain containing at least one dot, none of the parts holding whitespace or a
762	     * second {@code @}.
763	     */
764	    private static final java.util.regex.Pattern EMAIL_PATTERN =
765	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
