941	    /**
942	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
943	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
944	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
945	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
946	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
947	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
948	     * an {@link IllegalStateException} is thrown.
949	     *
950	     * @param input the string to hash
951	     * @param hexChars the number of leading upper-case hex characters to return
952	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
953	     */
954	    private String shaHex(String input, int hexChars) {
955	        try {
956	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
957	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
958	            StringBuilder sb = new StringBuilder();
959	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
960	                sb.append(String.format("%02X", digest[i]));
961	            }
962	            return sb.substring(0, hexChars);
963	        }
964	        catch (java.security.NoSuchAlgorithmException e) {
965	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
966	        }
967	    }
