1006	     * Stamps an owner with its household member count, the number of owners sharing its household
1007	     * (see {@link #countHouseholdMembers(String)}), so every value the owner derives from its
1008	     * household size (its membership factor and level) reads a populated count rather than the
1009	     * unstamped default. This is the single definition of hydrating an owner with its household
1010	     * member count, shared by the create and read paths that render an owner's derived values.
1011	     *
1012	     * @param owner the owner to stamp, mutated in place with its household member count
1013	     */
1014	    private void applyHouseholdMemberCount(Owner owner) {
1015	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1016	    }
1017	
1018	    /**
1019	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
1020	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
1021	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
1022	     *
1023	     * @param value the value to collapse, or {@code null}
1024	     * @return the whitespace-collapsed value, never {@code null}
1025	     */
1026	    private String collapseWhitespace(String value) {
1027	        if (value == null) {
1028	            return "";
1029	        }
1030	        return value.trim().replaceAll("\\s+", " ");
1031	    }
1032	
1033	    /**
1034	     * Common street-type abbreviations expanded during address normalization, keyed by their
1035	     * upper-cased token.
1036	     */
1037	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1038	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1039	
1040	    /**
1041	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1042	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1043	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1044	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1045	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1046	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1047	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1048	     * everywhere an address is stored or compared.
1049	     *
1050	     * @param address the submitted address value, or {@code null}
1051	     * @return the normalized address, never {@code null}
1052	     */
1053	    private String normalizeAddress(String address) {
1054	        if (address == null) {
1055	            return "";
1056	        }
1057	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1058	        if (collapsed.isEmpty()) {
1059	            return "";
1060	        }
1061	        String[] tokens = collapsed.split(" ");
1062	        StringBuilder sb = new StringBuilder(collapsed.length());
1063	        for (int i = 0; i < tokens.length; i++) {
1064	            if (i > 0) {
1065	                sb.append(' ');
1066	            }
1067	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1068	        }
1069	        return sb.toString();
1070	    }
1071	}
